\caption{Comparisons with prior distributions for margin-based active learning, disagreement-based active learning, and Baum's algorithm.}
\label{table: comparisons of distributions}
\centering


\begin{tabular}{c|ccc}
\hline
 & \multicolumn{2}{c}{Prior Work} & Ours\\
\hline
Margin (Efficient, Noise) & uniform~\cite{awasthi2014power} & log-concave~\cite{awasthi2017power} &  $s$-concave\\
Disagreement & uniform~\cite{hanneke2007bound} & nearly-log-concave~\cite{balcan2013active} & $s$-concave\\
Baum's & symmetric~\cite{baum1990polynomial} & log-concave~\cite{klivans2009baum} & $s$-concave\\
\hline
\end{tabular}

\medskip
\noindent{\textbf{Notations:}}
We will use capital or lower-case letters to represent random variables, $\mathcal{D}$ to represent an $s$-concave distribution, and $\mathcal{D}_{u,t}$ to represent the conditional distribution of $\mathcal{D}$ over the set $\{x:\ |u\cdot x|\le t\}$.

\label{theorem: generalized prekopa-leindler inequality}
Let $0<\lambda<1$, and $H_s$, $G_1$, and $G_2$ be non-negative integrable functions on $\mathbb{R}^m$ such that $H_s(\lambda x+(1-\lambda) y)\ge [\lambda G_1(x)^s\oplus(1-\lambda) G_2(y)^s]^{1/s}$ for every $x,y\in\mathbb{R}^m$. Then
$
\int_{\mathbb{R}^m}H_s(x)dx\ge \left[\lambda\left(\int_{\mathbb{R}^m}G_1(x)dx\right)^\gamma+(1-\lambda)\left(\int_{\mathbb{R}^m}G_2(x)dx\right)^\gamma\right]^{1/\gamma}
$ for $s\ge -1/m$,
with $\gamma=s/(1+ms)$.

\label{lemma: halfspace probability}
Let $X$ be drawn from a one-dimensional distribution with $s$-concave density for $-1/2\le s\le 0$. Then
$\Pr(X\ge \mathbb{E} X)\ge (1+\gamma)^{-1/\gamma}$ for $\gamma=s/(1+s)$.

\label{lemma: bound for 1 dim}
Let $g:\mathbb{R}\rightarrow\mathbb{R}_+$ be an isotropic $s$-concave density function and $s> -1/3$.
(a) For all $x$, $g(x)\le \frac{1+s}{1+3s}$;
(b) We have $g(0)\ge\sqrt{\frac{1}{3(1+\gamma)^{3/\gamma}}}$, where $\gamma=\frac{s}{s+1}$.

\label{lemma: more refined upper bound}
Let $f:\mathbb{R}^n\rightarrow \mathbb{R}_+$ be an isotropic $s$-concave density. Then $f(x)\le \beta_1(n,s)(1-s\beta_2(n,s)\|x\|)^{1/s}$ for every $x\in\mathbb{R}^n$, where
\begin{equation*}
\beta_1(n,s)=\frac{(2-2^{-(n+1)s})^{\frac{1}{s}}}{2\pi^{n/2}d^n}(1-s)^{-1/s}n\Gamma(n/2)\left[\left(\frac{1+\beta}{1+3\beta}\sqrt{3(1+\gamma)^{3/\gamma}}2^{n-1+1/s}\right)^{s}-1\right]^{1/s},
\end{equation*}
\begin{equation*}
\beta_2(n,s)=\frac{2\pi^{(n-1)/2}d^{n-1}}{(n-1)\Gamma((n-1)/2)}(2-2^{-ns})^{-\frac{1}{s}}\frac{[(a(n,s)+(1-s)\beta_1(n,s)^s)^{1+\frac{1}{s}}-a(n,s)^{1+\frac{1}{s}}]s}{\beta_1(n,s)^s(1+s)(1-s)},
\end{equation*}
$a(n,s)=(4e\pi)^{-ns/2}\left[\left(\frac{1+\beta}{1+3\beta}\sqrt{3(1+\gamma)^{3/\gamma}}2^{n-1+1/s}\right)^{s}-1\right]^{-1}$, $\gamma=\frac{\beta}{1+\beta}$,
$\beta=\frac{s}{1+(n-1)s}$, and $d=(1+\gamma)^{-\frac{1}{\gamma}}\frac{1+3\beta}{3+3\beta}$.

The proofs of Parts (a) and (b) are from \cite{lovasz2007geometry}.

(c) The intuition behind the proof is to choose a baseline $s$-concave function $h$ which is at the ``boundary" between the family of $s$-concave function and that of the non $s$-concave function. We show that $h$ satisfies the equation
\begin{equation}
\label{equ: equality for special function}
T_n(h)T_{n+2}(h)=T_{n+1}^2(h).
\end{equation}
Then by the facts that $h$ is at the ``boundary" and $g$ is any $s$-concave function, we have
\begin{equation}
\label{equ: comparison}
T_{n+1}(h)\le T_{n+1}(g).
\end{equation}
The conclusion follows from \eqref{equ: equality for special function} and \eqref{equ: comparison}, and from our choice of $h$ such that $T_n(h)=T_n(g)$ and $T_{n+2}(h)=T_{n+2}(g)$, by adjusting the slope and intercept of the linear function.

Formally, let $h(t)=\beta(1+\gamma t)^{1/s}$ be the above-mentioned baseline $s$-concave function ($\beta,\gamma>0$) such that
\begin{equation*}
M_n(h)=M_n(g)\ \ \ \ \mbox{and}\ \ \ \ M_{n+2}(h)=M_{n+2}(g)
\end{equation*}
(This holds because there are two parameters $\beta,\gamma$ and two equations). That means
\begin{equation*}
\int_0^\infty t^n(h(t)-g(t))dt=0\ \ \ \ \mbox{and}\ \ \ \ \int_0^\infty t^{n+2}(h(t)-g(t))dt=0.
\end{equation*}
Then it follows that the graph of $h$ must intersect the graph of $g$ at least twice. Since $g$ is $s$-concave, which implies the uni-modality, the graphs of $h$ and $g$ intersect exactly at two points $0\le a<b$. Moreover, $h\le g$ in the interval $[a,b]$ and $h\ge g$ outside the interval. That is to say, $(t-a)(t-b)$ has the same sign as $h-g$. Thus
\begin{equation*}
\int_0^{\infty} (t-a)(t-b)t^n(h(t)-g(t))dt\ge 0.
\end{equation*}
Namely,
\begin{equation*}
0=\int_0^{\infty}t^{n+2}(h(t)-g(t))dt+ab\int_0^{\infty}t^n(h(t)-g(t))dt\ge (a+b)\int_0^\infty t^{n+1}(h(t)-g(t))dt.
\end{equation*}
This implies that
\begin{equation*}
M_{n+1}(h)=\int_0^{\infty}t^{n+1}h(t)dt\le\int_0^\infty t^{n+1}g(t)dt=M_{n+1}(g).
\end{equation*}
Since
\begin{equation*}
\label{equ: integral}
M_n(h)=\int_0^\infty t^n\beta(1+\gamma t)^{1/s}dt=B(-1/s-n-1,n+1)\frac{\beta}{\gamma^{n+1}}
\end{equation*}
for $s>-1/(n+1)$, we have
\begin{equation*}
\begin{split}
\frac{M_n(g)}{B(-1/s-n-1,n+1)}\frac{M_{n+2}(g)}{B(-1/s-n-3,n+3)}&=\frac{M_n(h)}{B(-1/s-n-1,n+1)}\frac{M_{n+2}(h)}{B(-1/s-n-3,n+3)}\\
&=\frac{\beta}{\gamma^{n+1}}\cdot \frac{\beta}{\gamma^{n+3}}\\
&=\left(\frac{M_{n+1}(h)}{B(-1/s-n-2,n+2)}\right)^2\\
&\le \left(\frac{M_{n+1}(g)}{B(-1/s-n-2,n+2)}\right)^2,
\end{split}
\end{equation*}
as desired.

(d) The proof is almost the same as that of Part (c). Let $h(t)=\beta(1+\gamma t)^{1/s}$ be an $s$-concave function ($\beta,\gamma>0$) such that
\begin{equation*}
h(0)=g(0)\ \ \ \ \mbox{and}\ \ \ \ M_1(h)=M_1(g).
\end{equation*}
So the graphs of $h$ and $g$ intersect exactly at two points $0$ and $a>0$, and hence
\begin{equation*}
\int_0^{\infty}t(t-a)t^{-1}(h(t)-g(t))dt\ge 0.
\end{equation*}
That means
\begin{equation*}
0=\int_0^{\infty}t(h(t)-g(t))dt\ge a\int_0^{\infty}(h(t)-g(t))dt,
\end{equation*}
or equivalently,
\begin{equation*}
M_0(h)\le M_0(g).
\end{equation*}
Note that $h(0)M_1(h)=M_0(h)^2\frac{1+s}{1+2s}$ by \eqref{equ: integral}.
Then the conclusion follows by the fact
\begin{equation*}
g(0)M_1(g)=h(0)M_1(h)=M_0(h)^2\frac{1+s}{1+2s}\le M_0(g)^2\frac{1+s}{1+2s}.
\end{equation*}

(a) Let $z$ be the maximum point of function $g$. Intuitively, if the value of the function $g$ evaluated at $z$ is too large, the corresponding distribution has a small deviation from $z$ (Second part of the proof below). However, the moment property of Lemma \ref{lemma: moment property} restricts that the second moment cannot be too small (First part of the proof below), which leads to a contradiction.

Formally, suppose that $g(z)>\frac{1+s}{1+3s}$. Define
\begin{equation*}
M_i=\int_z^{\infty}(x-z)^ig(x)dx,\ \ \ \ \mbox{and}\ \ \ \ N_i=\int_{-\infty}^z(z-x)^ig(x)dx.
\end{equation*}
By the isotropicity of function $g$, we have
\begin{equation*}
M_0+N_0=1,\ \ \ \ N_1-M_1=z,\ \ \ \ M_2+N_2=1+z^2.
\end{equation*}
Thus
\begin{equation*}
\begin{split}
M_2+N_2&=(M_0+N_0)^2+(M_1-N_1)^2\\
&=(M_0-M_1)^2+(N_0-N_1)^2+2(M_0N_0-M_1N_1)+2(M_0M_1+N_0N_1)\\
&\ge 2(M_0M_1+N_0N_1),
\end{split}
\end{equation*}
where the last inequality holds since, by Lemma \ref{lemma: moment property} (d), we have $M_1\le\frac{M_0^2}{g(z)}\frac{1+s}{1+2s}\le M_0^2\le M_0$ and $N_1\le\frac{N_0^2}{g(z)}\frac{1+s}{1+2s}\le N_0^2\le N_0$.

On the other hand, by Lemma \ref{lemma: moment property} (c) (d),
\begin{equation*}
M_2\le \frac{2M_1^2}{M_0}\frac{1+2s}{1+3s}\le \frac{2M_1M_0}{g(z)}\frac{1+s}{1+3s}<2M_1M_0,
\end{equation*}
and similarly, $N_2<2N_1N_0$. That means
\begin{equation*}
M_2+N_2<2(M_0M_1+N_0N_1),
\end{equation*}
and we obtain a contradiction.


(b) The proof is by Lemma \ref{lemma: moment property} (b) which lower bounds $g(0)$ by the second order moment of $g$, which is $1$ according to isotropicity.

Specifically, without lose of generality, assume that $g(x)$ is monotone decreasing for $x\ge 0$ (otherwise consider $g(-x)$, since function $g$ is uni-modal). Define $g_0$ as the restriction of $g$ to the non-negative semi-line. Then by Lemma \ref{lemma: moment property} (b), we have
\begin{equation*}
M_1'(g_0)^3\le M_0'(g_0)^2M_3'(g_0),
\end{equation*}
which implies
\begin{equation*}
g(0)\ge \sqrt{\frac{M_0(g_0)^3}{3M_2(g_0)}}.
\end{equation*}
Note that $M_2(g_0)\le M_2(g)=1$, and by Lemma \ref{lemma: halfspace probability},
\begin{equation*}
M_0(g_0)=\int_0^\infty g(t)dt=\Pr[X\ge \mathbb{E} X]\ge (1+\gamma)^{-1/\gamma}.
\end{equation*}
Thus we have
\begin{equation*}
g(0)\ge \sqrt{\frac{1}{3(1+\gamma)^{3/\gamma}}},
\end{equation*}
where $\gamma=s/(1+s)$.

(a) 
Formally, suppose that the conclusion does not hold true, i.e., there is a point $u$ such that $\|u\|=t\le d$ and \red{$f(u)<\left(\frac{t}{d}((2-2^{-(n+1)s})^{-1}-1)+1\right)^{1/s}f(0)$}. Define $v=\frac{d}{t}u$ and note that $0\le \frac{t}{d}\le 1$. Therefore, by the $s$-concavity of $f$, we have
\begin{equation*}
f(u)=f\left(\frac{t}{d}v+\left(1-\frac{t}{d}\right)0\right)\ge \left[\frac{t}{d}f(v)^s+\left(1-\frac{t}{d}\right)f(0)^s\right]^{1/s},
\end{equation*}
which together with $f(u)<\left(\frac{t}{d}((2-2^{-(n+1)s})^{-1}-1)+1\right)^{1/s}f(0)$ implies \red{$f(v)<(2-2^{-(n+1)s})^{-1/s}f(0)$}. Let $H$ be a hyperplane supporting the convex set $\{x\in\mathbb{R}^n: f(x)\ge f(v)\}$ through the point $v$ (the convexity follows from the $s$-concavity of $f$). Define an orthogonal coordinate system in which the hyperplane is parallel to coordinate plane so that it can be represented as $x_1=a$ for some $0<a\le d$. Thus \red{$f(x)<(2-2^{-(n+1)s})^{-1/s}f(0)$} for any $x$ such that $x_1\ge a$. We will prove that this implies that the 1-dimensional marginal is not flat.

Denote by $g$ the first marginal of the $n$-dimensional function $f$. Then $g$ is isotropic and $\beta=\frac{s}{1+(n-1)s}$-concave by Theorem \ref{theorem: marginal}, and $g(x)\le \frac{1+\beta}{1+3\beta}$ for all $x$ by Lemma \ref{lemma: bound for 1 dim} (a). We prove that
\begin{equation*}
g(2b)<\frac{g(b)}{4}
\end{equation*}
for any $b\ge a$, which means that the 1-dimensional function is not flat.
To see this, by the $s$-concavity of function $f$, we have that, for every $x$ such that $x_1\ge a$,
\begin{equation*}
f(2x)^s\ge 2f(x)^s-f(0)^s>2^{-(n+1)s}f(x)^s.
\end{equation*}
Namely, $f(2x)< 2^{-(n+1)}f(x)$. Hence
\begin{equation*}
g(2b)=\int_{(x_1=2b)}f(x)dx_2...dx_n< 2^{-(n+1)}2^{n-1}\int_{(x_1=b)}f(x)dx_2...dx_n=\frac{g(b)}{4}.
\end{equation*}
So
\begin{equation*}
\int_a^\infty g(y)dy=\int_a^{2a} g(y)dy+\int_{2a}^\infty g(y)dy< \int_a^{2a} g(y)dy+\frac{1}{2}\int_a^{\infty} g(y)dy.
\end{equation*}
Namely, by Lemma \ref{lemma: bound for 1 dim} (a),
\begin{equation*}
\int_a^{\infty} g(y)dy< 2\int_a^{2a} g(y)dy\le 2a\frac{1+\beta}{1+3\beta}.
\end{equation*}
So
\begin{equation*}
\int_0^{\infty} g(y)dy=\int_0^a g(y)dy+\int_a^{\infty} g(y)dy< 3a\frac{1+\beta}{1+3\beta}\le 3d\frac{1+\beta}{1+3\beta}=(1+\gamma)^{-1/\gamma},
\end{equation*}
which leads to a contradiction with Lemma \ref{lemma: halfspace probability}.

(b) If $f(w)\le f(0)$ for every $w$, then the conclusion holds true. Otherwise, let $w$ be the point such that $f(w)> f(0)$. Let $H_0$ be the hyperplane through $0$ which supports the convex set $\{x\in\mathbb{R}^n:f(x)\ge f(0)\}$. By defining an orthogonal system, we may set $H_0$ as the hyperplane $x_1=0$, and so $f(x)\le f(0)$ for any $x$ such that $x_1=0$. Define $g$, which is a $\beta=\frac{s}{1+(n-1)s}$-concave function, as the first marginal of function $f$. Denote by $H_t$ the hyperplane $x_1=t$. Without loss of generality, we assume that $w\in H_b$ with $b>0$.

Let $x$ be any point on $H_0$ and $x'$ be the intersection between line segment $[x,w]$ and $H_{b/2}$. Then by the $s$-concavity of $f$ and $f(x)\le f(0)$ for $x\in H_0$, we have
\begin{equation*}
f(x')\ge \left[\frac{1}{2}f(x)^s+\frac{1}{2}f(w)^s\right]^{1/s}\ge\left(\frac{1}{2}\right)^{1/s}f(x)\left[1+\left(\frac{f(w)}{f(0)}\right)^{s}\right]^{1/s}.
\end{equation*}
Thus
\begin{equation*}
g(b/2)=\int_{(x_1=b/2)}f(x)dx_2...dx_n\ge\frac{1}{2^{n-1+1/s}}\left[1+\left(\frac{f(w)}{f(0)}\right)^{s}\right]^{1/s}g(0).
\end{equation*}
By Lemma \ref{lemma: bound for 1 dim} (a) (b), we have
\begin{equation*}
\frac{1+\beta}{1+3\beta}\ge g(b/2)\ge \frac{1}{2^{n-1+1/s}}\left[1+\left(\frac{f(w)}{f(0)}\right)^{s}\right]^{1/s}\sqrt{\frac{1}{3(1+\gamma)^{3/\gamma}}},
\end{equation*}
where $\gamma=\beta/(1+\beta)$. Note that $s\ge -\frac{1}{2n+3}$ implies $\frac{1+\beta}{1+3\beta}2^{n-1+1/s}\sqrt{3(1+\gamma)^{3/\gamma}}<1$. So
\begin{equation*}
f(w)\le f(0)\left[\left(\frac{1+\beta}{1+3\beta}\sqrt{3(1+\gamma)^{3/\gamma}}2^{n-1+1/s}\right)^{s}-1\right]^{1/s}.
\end{equation*}

(c) The proof of Part (c) follows from \cite{lovasz2007geometry}.

(d) The proof of lower bound follows from Parts (b) and (c).

For the upper bound, by Part (a), we have
\begin{equation*}
1=\int_{\mathbb{R}^n}f(x)dx\ge \int_{\|x\|\le d}f(x)dx\ge \red{d^n \text{vol}(B_{n-1})(2-2^{-(n+1)s})^{-1/s}f(0),}
\end{equation*}
where $\text{vol}(B_{n-1})$ represents the volume of $n-1$-dimensional unit ball. So
\begin{equation*}
f(0)\le \red{\frac{(2-2^{-(n+1)s})^{1/s}}{d^n\text{vol}(B_{n-1})}=(2-2^{-(n+1)s})^{1/s}\frac{n\Gamma(n/2)}{2\pi^{n/2}d^n}.}
\end{equation*}

(e) The proof of (e) follows from Parts (b) and (d).

(f) Define an orthogonal coordinate system in which $\ell$ is the $x_n$-axis. Let $h$ be the marginal of function $f$ over first $n-1$ variables, namely,
\begin{equation*}
h(x_1,...,x_{n-1})=\int f(x_1,...,x_{n-1},x_n)dx_n.
\end{equation*}
Then
\begin{equation*}
\int_{\ell} f=h(0)\le \red{(2-2^{-ns})^{1/s}\frac{(n-1)\Gamma((n-1)/2)}{2\pi^{(n-1)/2}d^{n-1}}.}
\end{equation*}

We first note that when $\|x\|\le 1/\beta_2$, $\beta_1(1-s\beta_2\|x\|)^{1/s}\ge \beta_1(1-s)^{1/s}\ge f(x)$ by Theorem \ref{theorem: upper and lower bounds} (e). So the conclusion holds.

We now assume that there is a point $v$ such that $\|v\|>1/\beta_2$ but $f(v)>\beta_1(1-s\beta_2\|v\|)^{1/s}$. Denote by $[0,v]$ the line segment between the origin $0$ and the point $v$, and let $\ell$ be the line through $v$ and $0$. We will prove that
\begin{equation*}
\int_\ell f > \red{(2-2^{-ns})^{1/s}\frac{(n-1)\Gamma((n-1)/2)}{2\pi^{(n-1)/2}d^{n-1}},}
\end{equation*}
which leads to a contradiction with Theorem \ref{theorem: upper and lower bounds} (f). Let $x$ be the convex combination of points $0$ and $v$, i.e., $x=(1-\|x\|/\|v\|)0+(\|x\|/\|v\|)v$, where $0\le \|x\|\le\|v\|$. Then by the $s$-concavity of $f$ and Theorem \ref{theorem: upper and lower bounds} (d),
\begin{equation*}
\begin{split}
f(x)&\ge \left[\left(1-\frac{\|x\|}{\|v\|}\right)f(0)^s+\frac{\|x\|}{\|v\|}f(v)^s\right]^{1/s}\\&> \red{\left[f(0)^s+\frac{\|x\|}{\|v\|}f(v)^s\right]^{1/s}}\\
&> \left[f(0)^s+\frac{\|x\|}{\|v\|}\beta_1^s-s\beta_1^s\beta_2\|x\|\right]^{1/s}\\&>\left[f(0)^s+(1-s)\beta_1^s\beta_2\|x\|\right]^{1/s}\\
&> \left\{(4e\pi)^{-ns/2}\left[\left(\frac{1+\beta}{1+3\beta}\sqrt{3(1+\gamma)^{3/\gamma}}2^{n-1+1/s}\right)^{s}-1\right]^{-1}+(1-s)\beta_1^s\beta_2\red{\|x\|}\right\}^{1/s}.
\end{split}
\end{equation*}
Thus
\begin{equation*}
\begin{split}
\int_\ell f\ge \int_{[0,v]}f&=\int_0^{\|v\|} \hspace{-0.2cm}\left\{(4e\pi)^{-ns/2}\left[\left(\frac{1+\beta}{1+3\beta}\sqrt{3(1+\gamma)^{3/\gamma}}2^{n-1+1/s}\right)^{s}\hspace{-0.2cm}-\hspace{-0.1cm}1\right]^{-1}\hspace{-0.3cm}+\hspace{-0.1cm}(1-s)\beta_1^s\beta_2r\right\}^{1/s}\hspace{-0.2cm} dr\\
&>\int_0^{1/\beta_2} \hspace{-0.2cm}\left\{(4e\pi)^{-ns/2}\left[\left(\frac{1+\beta}{1+3\beta}\sqrt{3(1+\gamma)^{3/\gamma}}2^{n-1+1/s}\right)^{s}\hspace{-0.2cm}-\hspace{-0.1cm}1\right]^{-1}\hspace{-0.3cm}+\hspace{-0.1cm}(1-s)\beta_1^s\beta_2r\right\}^{1/s}\hspace{-0.2cm} dr\\
&\ge \red{(2-2^{-ns})^{1/s}\frac{(n-1)\Gamma((n-1)/2)}{2\pi^{(n-1)/2}d^{n-1}}.}
\end{split}
\end{equation*}
So the proof is completed.

Define an orthogonal coordinate system in which $w$ is an axis. Then the distribution of $w\cdot x$ is equal to the first marginal of the distribution $\mathcal{D}$, with isotropic $\gamma=\frac{s}{1+(n-1)s}$-concave density $g$ by Theorem \ref{theorem: marginal}. According to the upper bound given by Lemma \ref{lemma: bound for 1 dim} (a),
\begin{equation*}
\Pr_{x\sim\mathcal{D}}[|w\cdot x|\le t]=\int_{-t}^t g(x)dx\le \frac{1+\gamma}{1+3\gamma}\int_{-t}^t dx=2\frac{1+ns}{1+(n+2)s}t.
\end{equation*}

We now prove the later part of the theorem by a similar argument. By Theorem \ref{theorem: upper and lower bounds} (a) (d), for 1-dimensional $\gamma$-concave density $f(u)$ and $\|u\|\le d$, we have
\begin{equation*}
\begin{split}
f(u)&\ge (2-2^{-2\gamma})^{-1/\gamma}f(0)\\
&>(2-2^{-2\gamma})^{-1/\gamma}(4e\pi)^{-1/2}\left(2\left(\frac{1+\gamma}{1+3\gamma}\sqrt{3}\left(\frac{1+2\gamma}{1+\gamma}\right)^{\frac{3+3\gamma}{2\gamma}}\right)^\gamma-1\right)^{-1/\gamma}\\
&\triangleq \frac{f_2(s,n)}{2}.
\end{split}
\end{equation*}
Therefore,
\begin{equation*}
\Pr_{x\sim\mathcal{D}}[|w\cdot x|\le t]=\int_{-t}^t g(x)dx> \frac{f_2(s,n)}{2}\int_{-t}^t dx=f_2(s,n)t.
\end{equation*}

Let $E$ be the event that we want to bound. Theorem \ref{theorem: marginal} implies that, without loss of generality, we can focus on the case when $n=2$. Then the projected distribution $\mathcal{D}_2$ has an $\alpha$-concave density, where $\alpha=\frac{s}{1+(n-2)s}$.

We first claim that each member $x$ of $E$ satisfies $\|x\|\ge f_4$. To see this, without loss of generality, we assume that $v\cdot x$ is positive. Then for any $x\in E$, $u\cdot x<0$, i.e., $\theta(u,x)\ge \pi/2$. Hence $\theta(x,v)\ge \theta(u,x)-\theta(u,v)\ge \pi/2-\theta$. Since $|v\cdot x|\ge f_4\theta$ implies $\|x\|\cos\theta(v,x)\ge f_4\theta$, we must have $\|x\|\cos(\pi/2-\theta)\ge f_4\theta$, namely, $\|x\|\ge f_4\theta/\sin(\theta)\ge f_4$. Let $\textup{\textsf{ball}}(r)$ denote the ball of radius $r$ centered at the origin. This implies that
\begin{equation*}
\Pr[E]=\sum_{i=1}^\infty \Pr[E\cap (\textup{\textsf{ball}}((i+1)f_4)-\textup{\textsf{ball}}(if_4))].
\end{equation*}

Denote by $f(x_1,x_2)$ the $\alpha$-concave density function of $\mathcal{D}_2$. For any term $i\ge 1$, by Lemma \ref{lemma: more refined upper bound}, we have
\begin{equation*}
\begin{split}
&\ \ \ \ \Pr[E\cap (\textup{\textsf{ball}}((i+1)f_4)-\textup{\textsf{ball}}(if_4))]\\
&=\int_{(x_1,x_2)\in \textup{\textsf{ball}}((i+1)f_4)-\textup{\textsf{ball}}(if_4)}1_E(x_1,x_2)f(x_1,x_2)dx_1dx_2\\
&\le \int_{(x_1,x_2)\in \textup{\textsf{ball}}((i+1)f_4)-\textup{\textsf{ball}}(if_4)}1_E(x_1,x_2)\beta_1(2,\alpha)(1-\alpha\beta_2(2,\alpha)\|x\|)^{1/\alpha}dx_1dx_2\\
&\le \beta_1(2,\alpha)\left(1-\alpha\beta_2(2,\alpha)if_4\right)^{1/\alpha}\int_{(x_1,x_2)\in \textup{\textsf{ball}}((i+1)f_4)-\textup{\textsf{ball}}(if_4)}1_E(x_1,x_2)dx_1dx_2\\
&\le \beta_1(2,\alpha)\left(1-\alpha\beta_2(2,\alpha)if_4\right)^{1/\alpha}\int_{(x_1,x_2)\in \textup{\textsf{ball}}((i+1)f_4)}1_E(x_1,x_2)dx_1dx_2.
\end{split}
\end{equation*}
Denote by $B_1$ the unit ball in $\mathbb{R}^2$. Notice that
\begin{equation*}
\int_{(x_1,x_2)\in \textup{\textsf{ball}}((i+1)f_4)}1_E(x_1,x_2)dx_1dx_2\le \text{vol}(B_1)(i+1)^2f_4^2\theta/\pi.
\end{equation*}
Thus
\begin{equation*}
\begin{split}
\Pr[E]&\le\sum_{i=1}^\infty \beta_1(2,\alpha)\left(1-\alpha\beta_2(2,\alpha)if_4\right)^{1/\alpha}\text{vol}(B_1)(i+1)^2f_4^2\theta/\pi\\
&\le \frac{4f_4^2}{\pi}\text{vol}(B_1)\beta_1(2,\alpha)\theta\sum_{i=1}^\infty (1-\alpha\beta_2(2,\alpha)if_4)^{1/\alpha}i^2\\
&\le \frac{4f_4^2}{\pi}\text{vol}(B_1)\beta_1(2,\alpha)\theta\int_0^\infty x^2(1-\alpha\beta_2(2,\alpha)f_4x)^{1/\alpha}dx\\
&=\frac{4f_4^2}{\pi}\text{vol}(B_1)\beta_1(2,\alpha) \frac{B(-1/\alpha-3,3)}{(-\alpha\beta_2(2,\alpha)f_4)^3}\times \theta\\
&=4\beta_1(2,\alpha) \frac{B(-1/\alpha-3,3)}{-\alpha^3\beta_2(2,\alpha)^3f_4}\times \theta.
\end{split}
\end{equation*}
Choosing $f_4(s,n)=\frac{4\beta_1(2,\alpha)B(-1/\alpha-3,3)}{-c_1f_1(s,n)\alpha^3\beta_2(2,\alpha)^3}$, the proof is completed.

\label{lemma: probability of outside of margin}
For $d$ given by Theorem \ref{theorem: upper and lower bounds} (a), there exist such that for any isotropic $s$-concave distribution $\mathcal{D}$, for any $a$ such that $\|a\|\le 1$ and $\|u-a\|\le r$, for any $0<t\le d$, and for any $K\ge 4$, we have
\begin{equation*}
\Pr_{X\sim \mathcal{D}_{u,t}}(|a\cdot x|> K\sqrt{r^2+t^2})\le \frac{4\beta_1(2,\eta)}{f_2(s,n)\beta_2(2,\eta)}\frac{1}{\eta+1}\left(1-c\eta\beta_2(2,\eta)K\sqrt{1+\left(\frac{t}{r}\right)^2}\right)^{\frac{\eta+1}{\eta}},
\end{equation*}
where $\beta_1(2,\eta)$, $\beta_2(2,\eta)$, and $Q(\gamma)$, are given by Lemma \ref{lemma: more refined upper bound} and Theorem \ref{theorem: probability within margin}, respectively, $\eta=\frac{s}{1+(n-2)s}$, and $c$ is an absolute constant.

Without loss of generality, we assume that $u=(1,0,...,0)$. Let $a'=(0,a_2,...,a_d)$ and $X=(x_1,x_2,...,x_d)\sim \mathcal{D}_{u,t}$. So the probability that we want to bound is
\begin{equation*}
\Pr_{X\sim \mathcal{D}_{u,t}}(|a\cdot x|> K\sqrt{r^2+t^2})=\frac{\Pr_{x\sim \mathcal{D}}(|a\cdot x|> K\sqrt{r^2+t^2},\ |x_1|\le t)}{\Pr_{x\sim \mathcal{D}}(|x_1|\le t)}.
\end{equation*}
According to Theorem \ref{theorem: probability within margin}, there is a function $Q(\gamma)$ such that the denominator obeys the following lower bound when $t\le d$:
\begin{equation*}
\Pr_{X\sim \mathcal{D}}(|x_1|\le t)\ge f_2(s,n)t.
\end{equation*}
So the remainder of the proof is to bound the numerator. Note that we have
\begin{equation*}
\begin{split}
\Pr_{x\sim \mathcal{D}}(|a\cdot x|> K\sqrt{r^2+t^2},\ |x_1|\le t)&\le \Pr_{x\sim \mathcal{D}}(|a'\cdot x|> K\sqrt{r^2+t^2}-t,\ |x_1|\le t)\\
&\le \Pr_{x\sim \mathcal{D}}(|a'\cdot x|> (K-1)\sqrt{r^2+t^2},\ |x_1|\le t).
\end{split}
\end{equation*}
Denote by $a''=\frac{a'}{\|a'\|}$. Define random variable $Y$ as $a''\cdot x$ and $Z$ as $x_1$ where $x\sim\mathcal{D}$. Then the joint distribution of $Y$ and $Z$ is isotropic $\beta$-concave with $\eta=\frac{s}{1+(n-2)s}$. Let $f(y,z)$ be the density of such a distribution. Then we can bound the numerator by
\begin{equation*}
\begin{split}
4\Pr_{x\sim \mathcal{D}}(a'\cdot x>(K-1)\sqrt{r^2+t^2},\ 0\le x_1\le t)&=4\Pr_{X\sim \mathcal{D}}(a''\cdot x>\frac{(K-1)\sqrt{r^2+t^2}}{\|a'\|},\ 0\le x_1\le t)\\
&\le 4\int_0^t\int_{\frac{(K-1)\sqrt{r^2+t^2}}{\|a'\|}}^\infty f(y,z) dydz.
\end{split}
\end{equation*}
By Lemma \ref{lemma: more refined upper bound}, we note that
\begin{equation*}
f(y,z)\le \beta_1(2,\eta)(1-\eta\beta_2(2,\eta)\sqrt{y^2+z^2})^{1/\eta}.
\end{equation*}
Therefore, the numerator can be upper bounded by
\begin{equation}
\begin{split}
&\quad \ 4\beta_1(2,\eta)\int_0^t\int_{\frac{(K-1)\sqrt{r^2+t^2}}{\|a'\|}}^\infty (1-\eta\beta_2(2,\eta)\sqrt{y^2+z^2})^{1/\eta} dydz\\
&\le 4\beta_1(2,\eta)\int_0^t\int_{\frac{(K-1)\sqrt{r^2+t^2}}{\|a'\|}}^\infty (1-\eta\beta_2(2,\eta)y)^{1/\eta} dydz\\
&=4t\beta_1(2,\eta)\int_{\frac{(K-1)\sqrt{r^2+t^2}}{\|a'\|}}^\infty (1-\eta\beta_2(2,\eta)y)^{1/\eta} dy\\
&=\frac{4t\beta_1(2,\eta)}{\beta_2(2,\eta)}\frac{1}{\eta+1}\left(1-\eta\beta_2(2,\eta)\frac{(K-1)\sqrt{r^2+t^2}}{\|a'\|}\right)^{\frac{\eta+1}{\eta}}.
\end{split}
\end{equation}
Note that $\|a'\|\le r$. Finally, we have
\begin{equation*}
\begin{split}
\Pr_{X\sim \mathcal{D}_{u,t}}(|a\cdot x|> K\sqrt{r^2+t^2})&\le \frac{4\beta_1(2,\eta)}{f_2(s,n)\beta_2(2,\eta)}\frac{1}{\eta+1}\left(1-\eta\beta_2(2,\eta)\frac{(K-1)\sqrt{r^2+t^2}}{r}\right)^{\frac{\eta+1}{\eta}}\\
&\le \frac{4\beta_1(2,\eta)}{f_2(s,n)\beta_2(2,\eta)}\frac{1}{\eta+1}\left(1-c\eta\beta_2(2,\eta)\frac{K\sqrt{r^2+t^2}}{r}\right)^{\frac{\eta+1}{\eta}},
\end{split}
\end{equation*}
for an absolute constant $c$.

\begin{equation*}
\Pr_{X\sim \mathcal{D}_{u,t}}(|a\cdot x|> K\sqrt{r^2+t^2})=\frac{\Pr_{x\sim \mathcal{D}}(|a\cdot x|> K\sqrt{r^2+t^2},\ |x_1|\le t)}{\Pr_{x\sim \mathcal{D}}(|x_1|\le t)}.
\end{equation*}

\begin{equation*}
\begin{split}
\Pr_{x\sim \mathcal{D}}(|a\cdot x|> K\sqrt{r^2+t^2},\ |x_1|\le t)&\le \Pr_{x\sim \mathcal{D}}(|a'\cdot x|> K\sqrt{r^2+t^2}-t,\ |x_1|\le t)\\
&\le \Pr_{x\sim \mathcal{D}}(|a'\cdot x|> (K-1)\sqrt{r^2+t^2},\ |x_1|\le t).
\end{split}
\end{equation*}

\begin{equation*}
\begin{split}
4\Pr_{x\sim \mathcal{D}}(a'\cdot x>(K-1)\sqrt{r^2+t^2},\ 0\le x_1\le t)&=4\Pr_{X\sim \mathcal{D}}(a''\cdot x>\frac{(K-1)\sqrt{r^2+t^2}}{\|a'\|},\ 0\le x_1\le t)\\
&\le 4\int_0^t\int_{\frac{(K-1)\sqrt{r^2+t^2}}{\|a'\|}}^\infty f(y,z) dydz.
\end{split}
\end{equation*}

Denote by $z=\sqrt{r^2+t^2}$. Then we have
\begin{equation}
\begin{split}
\mathbb{E}_{x\sim \mathcal{D}_{u,t}}[(a\cdot x)^2]&=\int_0^\infty \Pr_{x\sim \mathcal{D}_{u,t}}[(a\cdot x)^2\ge z]dz\\
&\le 16z^2+\int_{16z^2}^\infty \Pr_{x\sim \mathcal{D}_{u,t}}[(a\cdot x)^2\ge z]dz\\
&\le 16z^2+\frac{4\beta_1(2,\eta)}{f_2(s,n)\beta_2(2,\eta)}\frac{1}{\eta+1}\int_0^\infty\left(1-\eta\beta_2(2,\eta)\frac{c\sqrt{z}}{r}\right)^{\frac{\eta+1}{\eta}}dz\\
&=16z^2+\frac{8\beta_1(2,\eta)}{f_2(s,n)\beta_2(2,\eta)}\frac{1}{\eta+1}\int_0^\infty y\left(1-\eta\beta_2(2,\eta)\frac{cy}{r}\right)^{\frac{\eta+1}{\eta}}dy\\
&=16z^2+\frac{8\beta_1(2,\eta)}{f_2(s,n)\beta_2(2,\eta)}\frac{1}{\eta+1}C_0B(-1/\eta-3,2)\frac{r^2}{\eta^2\beta_2(2,\eta)^2}\\
&=\left(16+C_0\frac{8\beta_1(2,\eta)B(-1/\eta-3,2)}{f_2(s,n)\beta_2(2,\eta)^3(\eta+1)\eta^2}\right)r^2+16t^2\\
&\le \left(16+C_0\frac{8\beta_1(2,\eta)B(-1/\eta-3,2)}{f_2(s,n)\beta_2(2,\eta)^3(\eta+1)\eta^2}\right)(r^2+t^2),
\end{split}
\end{equation}
where $c$, $C_0$ are absolute constants.

Denote by $N$ the set of noisy examples. Let $\widetilde \mathcal{P}$ be the noisy distribution of $(x,y)$ where $x\sim \mathcal{D}$ and $y$ obeys the adversarial noise model. We have
\begin{equation*}
\begin{split}
&  \left| \mathbb{E}_{(x,y)\sim \widetilde \mathcal{P}_k} [\ell_{\tau_k}(w^*, x, y)] - \mathbb{E}_{(x,y)\sim  \mathcal{P}_k} [\ell_{\tau_k}(w^*, x, y)] \right| \\
& \qquad \leq
\left| \mathbb{E}_{(x,y)\sim  \widetilde \mathcal{P}_k} \left[ \mathbf{1}_{x\in N} \left( \ell_{\tau_k}(w^*, x, y) - \ell_{\tau_k}(w^*,  x, \textup{sign}(w^*\cdot x) )\right) \right] \right| \\
& \qquad \leq 2 ~ \mathbb{E}_{(x,y)\sim  \widetilde \mathcal{P}_k} \left[ \mathbf{1}_{x\in N} \left(\frac{|w^*\cdot x|}{\tau_k} \right) \right] \\
&\qquad \leq
\frac{2}{\tau_k} \sqrt{\Pr_{(x,y)\sim \widetilde \mathcal{P}_k}[x\in N]}  \times  \sqrt{\mathbb{E}_{(x,y)\sim \widetilde \mathcal{P}_k}[(w^*\cdot x)^2]} \qquad \text{(By Cauchy Schwarz)}\\
&\qquad \le \frac{2}{\tau_k}\sqrt{\frac{\eta}{\Pr_{\widetilde \mathcal{P}}(|w_{k-1}\cdot x|\le b_{k-1})}}\times \sqrt{f_5(r_k^2+b_{k-1}^2)} \qquad \text{(By Theorem \ref{theorem: 1-D variance})}\\
&\qquad \le \frac{2}{\tau_k}\sqrt{\frac{\eta f_5(r_k^2+b_{k-1}^2)}{f_2 b_{k-1}}}. \qquad \text{(By Theorem \ref{theorem: probability within margin})}\\
\end{split}
\end{equation*}

\begin{equation*}
\begin{split}
&  \left| \mathbb{E}_{(x,y)\sim \widetilde \mathcal{P}_k} [\ell_{\tau_k}(w^*, x, y)] - \mathbb{E}_{(x,y)\sim  \mathcal{P}_k} [\ell_{\tau_k}(w^*, x, y)] \right| \\
& \qquad \leq
\left| \mathbb{E}_{(x,y)\sim  \widetilde \mathcal{P}_k} \left[ \mathbf{1}_{x\in N} \left( \ell_{\tau_k}(w^*, x, y) - \ell_{\tau_k}(w^*,  x, \textup{sign}(w^*\cdot x) )\right) \right] \right| \\
& \qquad \leq 2 ~ \mathbb{E}_{(x,y)\sim  \widetilde \mathcal{P}_k} \left[ \mathbf{1}_{x\in N} \left(\frac{|w^*\cdot x|}{\tau_k} \right) \right] \\
&\qquad \leq
\frac{2}{\tau_k} \sqrt{\Pr_{(x,y)\sim \widetilde \mathcal{P}_k}[x\in N]}  \times  \sqrt{\mathbb{E}_{(x,y)\sim \widetilde \mathcal{P}_k}[(w^*\cdot x)^2]} \qquad \text{(By Cauchy Schwarz)}\\
&\qquad \le \frac{2}{\tau_k}\sqrt{\frac{\eta}{\Pr_{\widetilde \mathcal{P}}(|w_{k-1}\cdot x|\le b_{k-1})}}\times \sqrt{f_5(r_k^2+b_{k-1}^2)} \qquad \text{(By Theorem \ref{theorem: 1-D variance})}\\
&\qquad \le \frac{2}{\tau_k}\sqrt{\frac{\eta f_5(r_k^2+b_{k-1}^2)}{f_2 b_{k-1}}}. \qquad \text{(By Theorem \ref{theorem: probability within margin})}\\
\end{split}
\end{equation*}

\label{lemma: concentration}
Denote by $W$ the samples drawn from the noisy distribution $\widetilde \mathcal{P}_k$ and suppose that
$
|W|=O\left( \frac{[b_{k-1}s+\tau_k(1+ns)\sqrt{n}[1-(\delta/(\sqrt{n}(k+k^2)))^{s/(1+ns)}]+\tau_ks]^2}{\kappa^2\tau_k^2s^2}\left(n+\log \frac{k+k^2}{\delta}\right)\right).
$
Then with probability at least $1-\frac{\delta}{k+k^2}$, for all $w\in \textup{\textsf{ball}}(w_{k-1},r_k)$, we have
\begin{equation*}
\left|\mathbb{E}_{(x,y)\sim \widetilde\mathcal{P}_k}\ell(w,x,y)-\ell(w,W)\right|\le\kappa/16.
\end{equation*}

To establish the lemma, we apply some standard VC tools (Theorem \ref{theorem: pseudo-dimension argument}). Note that the pseudo-dimension of $\{\ell(w,\cdot):w\in\mathbb{R}^n\}$ is at most $n$~\cite{awasthi2014power}. To use Theorem \ref{theorem: pseudo-dimension argument}, we first provide the upper bound on the loss. On one hand, note that
\begin{equation*}
\begin{split}
\ell(w,x,y)&\le 1+\frac{|w\cdot x|}{\tau_k}\le 1+\frac{|w_{k-1}\cdot x|+\|w-w_{k-1}\|\|x\|}{\tau_k}\\
&\le 1+\frac{b_{k-1}+\tau_k\|x\|}{\tau_k}.
\end{split}
\end{equation*}
On the other hand, by Theorem \ref{theorem: tail probability} and the union bound, with probability at least $1-\frac{\delta}{k+k^2}$, we have that
$
\max_{x\in W} \|x\|\le C\frac{(1+ns)\sqrt{n}}{s}\left\{1-\left[\frac{\delta}{6(k+k^2)|W|}\right]^{s/(1+ns)}\right\},
$
for an absolute constant $C$. The conclusion then follows from Theorem \ref{theorem: pseudo-dimension argument}.

\begin{equation*}
\begin{split}
\textup{\textsf{err}}_{\mathcal{D}_{w_{k-1},b_{k-1}}}(w_k)&=\textup{\textsf{err}}_{\mathcal{D}_{w_{k-1},b_{k-1}}}(v_k)\\
&\le \mathbb{E}_{(x,y)\sim \mathcal{P}_k}\ell(v_k,x,y)\\
&\le \mathbb{E}_{(x,y)\sim \widetilde \mathcal{P}_k}\ell(v_k,x,y)+\frac{2}{\tau_k}\sqrt{\frac{\eta f_5(r_k^2+b_{k-1}^2)}{f_2 b_{k-1}}} \qquad\text{(By Lemma \ref{lemma: distance between clean and noisy distribution})}\\
&\le \ell(v_k,W)+\frac{2}{\tau_k}\sqrt{\frac{\eta f_5(r_k^2+b_{k-1}^2)}{f_2 b_{k-1}}}+\frac{\kappa}{16} \qquad\text{(By Lemma \ref{lemma: concentration})}\\
&\le \ell(w^*,W)+\frac{4}{\tau_k}\sqrt{\frac{\eta f_5(r_k^2+b_{k-1}^2)}{f_2 b_{k-1}}}+\frac{\kappa}{8}\qquad \text{(Since $\|v_k\|\ge 1/2$)}\\
&\le \mathbb{E}_{(x,y)\sim \widetilde \mathcal{P}_k}\ell(w^*,x,y)+\frac{4}{\tau_k}\sqrt{\frac{\eta f_5(r_k^2+b_{k-1}^2)}{f_2 b_{k-1}}}+\frac{\kappa}{4} \qquad\text{(By Lemma \ref{lemma: concentration})}\\
&\le \mathbb{E}_{(x,y)\sim \mathcal{P}_k}\ell(w^*,x,y)+\frac{6}{\tau_k}\sqrt{\frac{\eta f_5(r_k^2+b_{k-1}^2)}{f_2 b_{k-1}}}+\frac{\kappa}{4} \qquad\text{(By Lemma \ref{lemma: distance between clean and noisy distribution})}\\
&\le \frac{6}{\tau_k}\sqrt{\frac{\eta f_5(r_k^2+b_{k-1}^2)}{f_2 b_{k-1}}}+\frac{\kappa}{2} \qquad\text{(By Lemma \ref{lemma: upper bound of expected loss})}\\
&\le \kappa,
\end{split}
\end{equation*}

Let $u_1$, $u_2$, and $u_3$ be normals to the hyperplanes bounding the region $R$, namely $R=\{x\in\mathbb{R}^n: u_1\cdot x\ge0\ \mbox{and}\ u_2\cdot x\ge 0\ \mbox{and}\ u_3\cdot x\ge 0\}$. Denote by $U$ the linear span of vectors $u_1$, $u_2$, and $u_3$, and let $(e_1,e_2,e_3)$ be an orthogonal basis of $U$ and $(e_1,e_2,e_3,...,e_n)$ be an extension of basis $(e_1,e_2,e_3)$ to $\mathbb{R}^n$. Represent the components of $x$, $u_1$, $u_2$, and $u_3$ in term of basis $(e_1,e_2,e_3,...,e_n)$ as
\begin{equation*}
x=(x_1,x_2,x_3,x_4,...,x_n),
\end{equation*}
\begin{equation*}
u_1=(u_{1,1},u_{1,2},u_{1,3},0,...,0),
\end{equation*}
\begin{equation*}
u_2=(u_{2,1},u_{2,2},u_{2,3},0,...,0),
\end{equation*}
\begin{equation*}
u_3=(u_{3,1},u_{3,2},u_{3,3},0,...,0).
\end{equation*}
Denote by $\textsf{proj}_U(x)\triangleq(x_1,x_2,x_3)$ the projection of $x$ onto subspace $U$, and let $\textsf{proj}_U(R)$ be the projection of $R$ onto $U$. Because the dot products of a point with normal vectors of $R$ are all that is needed to determine the membership in $R$, we have
\begin{equation}
\label{equ: membership in original and projected space}
\begin{split}
x\in R&\Leftrightarrow u_{j,1}x_1+u_{j,2}x_2+u_{j,3}x_3\ge 0\mbox{ for all }j\in\{1,2,3\}\\
&\Leftrightarrow \textsf{proj}_U(x)\in\textsf{proj}_U(R).
\end{split}
\end{equation}
Let $f$ be the density of the isotropic $s$-concave distribution and $g$ be the marginal density of $f$ w.r.t. $(x_1,x_2,x_3)$. Thus by \eqref{equ: membership in original and projected space},
\begin{equation*}
\begin{split}
\Pr[x\in R]&={\int\cdots\int}_R f(x_1,x_2,x_3,x_4,...,x_n)dx_1...dx_n\\
&={\int\int\int}_{\textsf{proj}_U(R)} g(x_1,x_2,x_3)dx_1dx_2dx_3.
\end{split}
\end{equation*}
Note that $f$ is isotropic and $s$-concave. So according to Theorem \ref{theorem: marginal}, $g$ is isotropic and $\kappa$-concave with $\kappa=s/(1+(n-3)s)$. We now use Theorem \ref{theorem: upper and lower bounds} and Lemma \ref{lemma: more refined upper bound} to bound $g$. Specifically, let $u\triangleq(x_1,x_2,x_3)$. On one hand, according to Theorem \ref{theorem: upper and lower bounds} (a) and (d), for any $u\in\mathbb{R}^3$ such that $\|u\|\le d$,
\begin{equation*}
\begin{split}
&g(u)\ge \left(\frac{\|u\|}{d}((2-2^{-4\kappa})^{-1}-1)+1\right)^{1/\kappa}f(0)\\
&>\left(\frac{\|u\|}{d}((2-2^{-4\kappa})^{-1}-1)+1\right)^{1/\kappa}(4e\pi)^{-3/2}\left[\left(\frac{1+\beta}{1+3\beta}\sqrt{3(1+\gamma)^{3/\gamma}}2^{2+1/\kappa}\right)^{\kappa}-1\right]^{-1/\kappa}\\
&\triangleq \|u\|^{1/\kappa}h(\kappa),
\end{split}
\end{equation*}
where $d=(1+\gamma)^{-1/\gamma}\frac{1+3\beta}{3+3\beta}$, $\beta=\frac{\kappa}{1+2\kappa}$, $\gamma=\frac{\kappa}{1+\kappa}$, and
\begin{equation*}
h(\kappa)=\left(\frac{1}{d}((2-2^{-4\kappa})^{-1}-1)+1\right)^{1/\kappa}(4e\pi)^{-3/2}\left[\left(\frac{1+\beta}{1+3\beta}\sqrt{3(1+\gamma)^{3/\gamma}}2^{2+1/\kappa}\right)^{\kappa}-1\right]^{-1/\kappa}.
\end{equation*}
On the other hand, by Lemma \ref{lemma: more refined upper bound}, for every $u\in\mathbb{R}^3$,
\begin{equation*}
g(u)\le\beta_1(3,\kappa)(1-\kappa\beta_2(3,\kappa)\|u\|)^{1/\kappa},
\end{equation*}
where
\begin{equation*}
\red{\beta_1(3,\kappa)=(2-2^{-4\kappa})^{1/\kappa}\frac{1}{2\pi^{3/2}d^3}(1-\kappa)^{-1/\kappa}3\Gamma(3/2)\left[\left(\frac{1+\beta}{1+3\beta}\sqrt{3(1+\gamma)^{3/\gamma}}2^{2+1/\kappa}\right)^{\kappa}-1\right]^{1/\kappa},}
\end{equation*}
\begin{equation*}
\red{\beta_2(3,\kappa)=\frac{2\pi d^2}{2}(2-2^{-3s})^{-1/s}\frac{[(a+(1-s)\beta_1(3,\kappa)^\kappa)^{1+1/\kappa}-a^{1+1/\kappa}]\kappa}{\beta_1(3,\kappa)^s(1+\kappa)(1-\kappa)},}
\end{equation*}
and
\begin{equation*}
a=(4e\pi)^{-3\kappa/2}\left[\left(\frac{1+\beta}{1+3\beta}\sqrt{3(1+\gamma)^{3/\gamma}}2^{2+1/\kappa}\right)^{\kappa}-1\right]^{-1}.
\end{equation*}
Denote by $R'=\textsf{proj}_U(R)\cap \textup{\textsf{ball}}(0,d)$, and $\textup{\textsf{ball}}(0,d)$ is the origin-centered ball of radius $d$ in $\mathbb{R}^3$. Thus we have
\begin{equation*}
\begin{split}
\int\int\int_{R'}\|u\|^{1/\kappa}h(\kappa)&du_1du_2du_3\le \Pr[x\in R]\\
&\le \int\int\int_{\textsf{proj}_U(R)}\beta_1(3,\kappa)(1-\kappa\beta_2(3,\kappa)\|u\|)^{1/\kappa}du_1du_2du_3.
\end{split}
\end{equation*}
Let $A\triangleq\int\int_{\textsf{proj}_U(R)\cap\mathbb{S}^2} sin\theta d\varphi d\theta$. Note that
\begin{equation*}
\int\int\int_{R'}\|u\|^{1/\kappa}h(\kappa)du_1du_2du_3=A\int_0^d r^2r^{1/\kappa}h(\kappa)dr=Ah(\kappa)\frac{1}{3+1/\kappa}d^{3+1/\kappa},
\end{equation*}
and
\begin{equation*}
\begin{split}
&\int\int\int_{\textsf{proj}_U(R)}\beta_1(3,\kappa)(1-\kappa\beta_2(3,\kappa)\|u\|)^{1/\kappa}du_1du_2du_3\\
&=A\beta_1(3,\kappa)\int_0^\infty r^2(1-\kappa\beta_2(3,\kappa) r)^{1/\kappa}dr\\
&=A\beta_1(3,\kappa)\frac{B(-1/\kappa-3,3)}{(-\kappa\beta_2(3,\kappa))^3}.
\end{split}
\end{equation*}
So we have
\begin{equation*}
Ah(\kappa)\frac{1}{3+1/\kappa}d^{3+1/\kappa}\le\Pr[x\in R]\le A\beta_1(3,\kappa)\frac{B(-1/\kappa-3,3)}{(-\kappa\beta_2(3,\kappa))^3},
\end{equation*}
and by symmetry,
\begin{equation*}
Ah(\kappa)\frac{1}{3+1/\kappa}d^{3+1/\kappa}\le\Pr[x\in -R]\le A\beta_1(3,\kappa)\frac{B(-1/\kappa-3,3)}{(-\kappa\beta_2(3,\kappa))^3}.
\end{equation*}
Therefore,
\begin{equation*}
\Pr[x\in -R]\le \Pr[x\in R]\beta_1(3,\kappa)\frac{B(-1/\kappa-3,3)}{(-\kappa\beta_2(3,\kappa))^3}\frac{3+1/\kappa}{h(\kappa)d^{3+1/\kappa}}.
\end{equation*}

\begin{equation}
\label{equ: membership in original and projected space}
\begin{split}
x\in R&\Leftrightarrow u_{j,1}x_1+u_{j,2}x_2+u_{j,3}x_3\ge 0\mbox{ for all }j\in\{1,2,3\}\\
&\Leftrightarrow \textsf{proj}_U(x)\in\textsf{proj}_U(R).
\end{split}
\end{equation}

Denote by $p$ the probability of observing a positive example. We discuss the following three cases.

\noindent{\textbf{1.} $r<m_2$ and $p<\epsilon$\textbf{.}}

In this case, the hypothesis that labels every examples as negative has error less than $\epsilon$. Therefore, the algorithm behaves with error at most $\epsilon$ when $r<m_2$.

\noindent{\textbf{2.} $r<m_2$ and $p\ge\epsilon$\textbf{.}}

By the Hoeffding inequality,
\begin{equation*}
\Pr(r<m_2)\le \Pr\left(\frac{r}{m_3}<\frac{\epsilon}{2}\right)\le \Pr\left(\frac{r}{m_3}<p-\frac{\epsilon}{2}\right)\le e^{-m_3\epsilon^2/2}\le\delta/4.
\end{equation*}
So the probability that this case happens is at most $\delta/4$.

\noindent{\textbf{3.} $r\ge m_2$\textbf{.}}

We note that
\begin{equation}
\label{equ: error of h}
\textup{\textsf{err}}(h)=\Pr(-H')\Pr(H_u\cap H_v|-H')+\Pr(H')\Pr(h_{xor}(x)\not=c(x)|x\in H'),
\end{equation}
where $c:\mathbb{R}^n\rightarrow \{-1,1\}$ is the hypothesis w.r.t. $H_u\cap H_v$. Observe that
\begin{equation*}
\Pr(-H')\Pr(H_u\cap H_v|-H')=\Pr(H_u\cap H_v)\Pr(-H'|H_u\cap H_v),
\end{equation*}
where $\Pr(-H'|H_u\cap H_v)$ is the error of $H'$ over the distribution conditioned on $H_u\cap H_v$. Since the VC argument works for any distribution, and $H'$ contains all $r\ge m_2$ positive examples according to Step 5 in Algorithm \ref{algorithm: intersections of halfspaces}, by the VC argument, with probability at least $1-\delta/4$,
\begin{equation*}
\Pr(-H'|H_u\cap H_v)\le \max\left\{\frac{\delta}{4(1+\gamma)^{1/\gamma} Km_1},\frac{\epsilon}{2}\right\}.
\end{equation*}
So
$
\Pr(-H')\Pr(H_u\cap H_v|-H')=\Pr(H_u\cap H_v\cap (-H'))\le \Pr(-H'|H_u\cap H_v)\le \max\left\{\frac{\delta}{4(1+\gamma)^{1/\gamma}Km_1},\frac{\epsilon}{2}\right\}\le \frac{\epsilon}{2}.
$

We now bound the second term in \eqref{equ: error of h}. According to Lemma \ref{lemma: isotropic reflection},
\begin{equation*}
\Pr((-H_u)\cap(-H_v)\cap H')\le K\Pr(H_u\cap H_v\cap (-H'))\le \frac{\delta}{4(1+\gamma)^{1/\gamma}m_1}.
\end{equation*}
On the other hand, by Lemma \ref{lemma: probability of halfspace}, $\Pr(H')\ge (1+\gamma)^{-1/\gamma}$ with $\gamma=s/(1+ns)$. Thus
\begin{equation*}
\Pr((-H_u)\cap (-H_v)|H')=\frac{\Pr((-H_u)\cap(-H_v)\cap(H'))}{\Pr(H')}\le \frac{\delta}{4m_1}.
\end{equation*}
That is to say, each point in $S$ has probability at most $\delta/(4m_1)$ of being in $(-H_u)\cap(-H_v)$. So by the union bound, with probability at least $1-\delta/4$, none of points in $S$ is in $(-H_u)\cap(-H_v)$. Therefore, Step 6 in Algorithm \ref{algorithm: intersections of halfspaces} is able to find $h_{xor}$ that is consistent with all the instances in $S$. Then by the VC argument, we have
\begin{equation*}
\Pr(h_{xor(x)}\not= c(x)|x\in H')\le \frac{\epsilon}{2},
\end{equation*}
with probability at least $1-\delta/4$. In summary, we have
\begin{equation*}
\begin{split}
\textup{\textsf{err}}(h)&=\Pr(-H')\Pr(H_u\cap H_v|-H')+\Pr(H')\Pr(h_{xor}(x)\not=c(x)|x\in H')\\
&\le \frac{\epsilon}{2}+\frac{\epsilon}{2}=\epsilon,
\end{split}
\end{equation*}
with failure probability at most $\delta/4+\delta/4+\delta=\delta$ by the union bound. Therefore, the proof is completed.

\caption{Margin Based Active Learning under S-Concave Distributions (Realizable Case)}
\begin{algorithmic}
\label{algorithm: margin based active learning realizable case}
\STATE {\bfseries Input:} $b_k=\min\{\Theta(2^{-k}f_4f_1^{-1}),d\}$, $m_k=C\left(\frac{f_3b_{k-1}}{2^{-k}}\left(n\log \frac{f_3b_{k-1}}{2^{-k}}+\log \frac{1+s-k}{\delta}\right)\right)$, and $T=\lceil\log \frac{1}{c\epsilon}\rceil$.
\STATE {\bfseries 1:} Draw $m_1$ examples from $\mathcal{D}$, label them and put them into $W(1)$.
\STATE {\bfseries 2:} \textbf{For} $k=1,2,...,T$
\STATE {\bfseries 3:} \quad Find a hypothesis $w_k$ with $\|w_k\|=1$ that is consistent with $W(k)$.
\STATE {\bfseries 4:} \quad $W(k+1)\leftarrow W(k)$.
\STATE {\bfseries 5:} \quad \textbf{While} $m_{k+1}$ additional data points are not labeled
\STATE {\bfseries 6:} \quad \quad Draw sample $x$ from $\mathcal{D}$.
\STATE {\bfseries 7:} \quad \quad \textbf{If} $|w_k\cdot x|\ge b_k$
\STATE {\bfseries 8:} \quad \quad \quad Reject $x$.
\STATE {\bfseries 9:} \quad \quad \textbf{Else}
\STATE {\bfseries 10:} \quad \quad \quad Ask for label of $x$ and put into $W(k+1)$.
\STATE {\bfseries 11:} \quad \ \ \textbf{End If}
\STATE {\bfseries 12:} \ \ \textbf{End While}
\STATE {\bfseries 13:} \textbf{End For}
\STATE {\bfseries Output:} Hypothesis $w_T$.
\end{algorithmic}

\floatname{algorithm}{Procedure}
\caption{Margin Based Active Learning under S-Concave Distributions (Adversarial Noise)}
\begin{algorithmic}
\STATE {\bfseries Input:} Parameters $b_k$, $\tau_k$, $r_k$, $m_k$, $\kappa$, and $T$ as in Theorem \ref{theorem: margin-based active learning adversarial noise}.
\STATE {\bfseries 1:} Draw $m_1$ examples from $\mathcal{D}$, label them and put them into $W$.
\STATE {\bfseries 2:} \ \ \textbf{For} $k=1,2,...,T$
\STATE {\bfseries 3:} \quad Find $v_k\in \textup{\textsf{ball}}(w_{k-1},r_k)$ to approximately minimize the hinge loss over $W$ s.t. $\|v_k\|\le 1$:\\
\qquad\ $\ell_{\tau_k}\le \min_{w\in \textup{\textsf{ball}}(w_{k-1},r_k)\cap \textup{\textsf{ball}}(0,1)} \ell_{\tau_k}(w,W)+\kappa/8$.
\STATE {\bfseries 4:} \quad Normalize $v_k$, yielding $w_k=\frac{v_k}{\|v_k\|}$.
\STATE {\bfseries 5:} \quad Clear the working set $W$.
\STATE {\bfseries 6:} \quad \textbf{While} $m_{k+1}$ additional data points are not labeled
\STATE {\bfseries 7:} \quad \quad Draw sample $x$ from $\mathcal{D}$.
\STATE {\bfseries 8:} \quad \quad \textbf{If} $|w_k\cdot x|\ge b_k$, reject $x$; \textbf{else} ask for label of $x$ and put into $W$.
\STATE {\bfseries 9:} \ \ \ \ \textbf{End While}
\STATE {\bfseries 10:} \textbf{End For}
\STATE {\bfseries Output:} Hypothesis $w_T$.
\end{algorithmic}

\caption{Learning Intersections of Halfspaces under S-Concave Distributions}
\begin{algorithmic}
\label{algorithm: intersections of halfspaces}
\STATE {\bfseries Input:} Parameters $m_1$, $m_2$, and $m_3$ as in Theorem \ref{theorem: Baum's algorithm}.
\STATE {\bfseries 1:} Draw $m_3$ examples. Denote by $r$ the number of observed positive examples.
\STATE {\bfseries 2:} \textbf{If} $r<m_2$, output the hypothesis that labels every point as negative, and end the algorithm.
\STATE {\bfseries 3:} Learn an origin-centered halfspace $H'$ which contains all $r$ positive examples.
\STATE {\bfseries 4:} Draw a set $S$ of $m_1$ i.i.d. examples in $H'$. Learn a weight vector $w\in\mathbb{R}^{n\times n}$ such that the hypothesis
$h_{xor}=\textup{sign}\left(\sum_{i=1}^n\sum_{j=1}^n w_{ij}x_ix_j\right)$
is consistent with the set $S$.
\STATE {\bfseries Output:} $h:\mathbb{R}^n\rightarrow\{-1,1\}$ such that $h(x)=h_{xor}(x)$ if $x\in H'$; Otherwise, $h(x)=-1$.
\end{algorithmic}

\label{theorem: vc theory}
Denote by $\mathcal{C}$ a class of concepts from a set $X$ to $\{-1,1\}$ with VC dimension $n$. Let $c\in\mathcal{C}$, and assume that
\begin{equation*}
M(\epsilon,\delta,n)=O\left(\frac{n}{\epsilon}\log \frac{1}{\epsilon}+\frac{1}{\epsilon}\log\frac{1}{\delta}\right)
\end{equation*}
examples $x_1,...,x_M$ are sampled from any probability distribution $\mathcal{D}$ over $X$. Then any hypothesis $h\in\mathcal{C}$ which is consistent with $c$ on $x_1,...,x_M$ has error at most $\epsilon$, with probability at least $1-\delta$.

\label{theorem: pseudo-dimension argument}
Let $F$ be a set of functions mapping from domain $X$ to $[a,b]$, and let $n$ be the pseudo-dimension of $F$. Then for any distribution $\mathcal{D}$ over $X$ and $m=O\left(\frac{(b-a)^2}{\kappa^2}(d+\log (1/\delta))\right)$, if $x_1,...,x_m$ are drawn independently from $\mathcal{D}$, with probability at least $1-\delta$, for all $f\in F$,
\begin{equation*}
\left|\mathbb{E}_{x\sim \mathcal{D}}f(x)-\frac{1}{m}\sum_{i=1}^mf(x_i)\right|\le \kappa.
\end{equation*}
